import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from './context/AuthContext';

/* ── Layouts ── */
import PublicLayout from './layouts/PublicLayout';
import AuthLayout  from './layouts/AuthLayout';
import FarmerLayout from './layouts/FarmerLayout';
import OwnerLayout  from './layouts/OwnerLayout';
import AdminLayout  from './layouts/AdminLayout';

/* ── Public Pages ── */
import WelcomePage  from './pages/public/WelcomePage';
import ExplorePage  from './pages/public/ExplorePage';

/* ── Auth Module Pages ── */
import RoleSelectionPage   from './pages/auth/RoleSelectionPage';
import LoginPage           from './pages/auth/LoginPage';
import RegisterPage        from './pages/auth/RegisterPage';
import ForgotPasswordPage  from './pages/auth/ForgotPasswordPage';
import OTPVerificationPage from './pages/auth/OTPVerificationPage';
import ResetPasswordPage   from './pages/auth/ResetPasswordPage';
import VerifySuccessPage   from './pages/auth/VerifySuccessPage';

/* ── Legacy Auth Route Wrappers ── */
import FarmerLogin    from './pages/auth/FarmerLogin';
import FarmerRegister from './pages/auth/FarmerRegister';
import OwnerLogin     from './pages/auth/OwnerLogin';
import OwnerRegister  from './pages/auth/OwnerRegister';
import AdminLogin     from './pages/auth/AdminLogin';

/* ── Farmer Pages ── */
import FarmerDashboard           from './pages/farmer/FarmerDashboard';
import EquipmentSearch           from './pages/farmer/EquipmentSearch';
import EquipmentDetail           from './pages/farmer/EquipmentDetail';
import EquipmentAvailabilityPage from './pages/farmer/EquipmentAvailabilityPage';
import RentalDurationPage        from './pages/farmer/RentalDurationPage';
import BookingConfirm            from './pages/farmer/BookingConfirm';
import MarketplacePage           from './pages/farmer/MarketplacePage';
import ProductDetail             from './pages/farmer/ProductDetail';
import CartPage                  from './pages/farmer/CartPage';
import CheckoutPage              from './pages/farmer/CheckoutPage';
import PaymentPage               from './pages/farmer/PaymentPage';
import OrderSuccessPage          from './pages/farmer/OrderSuccessPage';
import MyOrdersPage              from './pages/farmer/MyOrdersPage';
import SprayerServices           from './pages/farmer/SprayerServices';
import SprayerDetail             from './pages/farmer/SprayerDetail';
import ServiceBookingTimePage    from './pages/farmer/ServiceBookingTimePage';
import ServiceLocationPage       from './pages/farmer/ServiceLocationPage';
import ServiceBookingSummaryPage from './pages/farmer/ServiceBookingSummaryPage';
import ServiceBookingSuccessPage from './pages/farmer/ServiceBookingSuccessPage';
import SprayerHistoryPage        from './pages/farmer/SprayerHistoryPage';
import BookingHistory            from './pages/farmer/BookingHistory';
import AiDoctorHome              from './pages/farmer/AiDoctorHome';
import AiDoctorUpload            from './pages/farmer/AiDoctorUpload';
import AiDoctorResult            from './pages/farmer/AiDoctorResult';
import AiDoctorReport            from './pages/farmer/AiDoctorReport';
import AiDoctorHistory           from './pages/farmer/AiDoctorHistory';
import FarmerProfilePage         from './pages/farmer/FarmerProfilePage';
import EditProfilePage           from './pages/farmer/EditProfilePage';
import NotificationsPage         from './pages/farmer/NotificationsPage';
import SettingsPage              from './pages/farmer/SettingsPage';

/* ── Owner Pages ── */
import OwnerDashboard      from './pages/owner/OwnerDashboard';
import OwnerEquipment      from './pages/owner/OwnerEquipment';
import AddEquipment        from './pages/owner/AddEquipment';
import EditEquipment       from './pages/owner/EditEquipment';
import OwnerBookings       from './pages/owner/OwnerBookings';
import OwnerCalendar       from './pages/owner/OwnerCalendar';
import OwnerEarnings       from './pages/owner/OwnerEarnings';
import OwnerReviews        from './pages/owner/OwnerReviews';
import OwnerNotifications  from './pages/owner/OwnerNotifications';
import OwnerProfile        from './pages/owner/OwnerProfile';
import OwnerEditProfile    from './pages/owner/OwnerEditProfile';


/* ── Operator Pages ── */
import OperatorLayout         from './layouts/OperatorLayout';
import OperatorDashboard      from './pages/operator/OperatorDashboard';
import OperatorJobs           from './pages/operator/OperatorJobs';
import OperatorJobDetails     from './pages/operator/OperatorJobDetails';
import OperatorCalendar       from './pages/operator/OperatorCalendar';
import OperatorEarnings       from './pages/operator/OperatorEarnings';
import OperatorCustomers      from './pages/operator/OperatorCustomers';
import OperatorReviews        from './pages/operator/OperatorReviews';
import OperatorNotifications  from './pages/operator/OperatorNotifications';
import OperatorProfile        from './pages/operator/OperatorProfile';
import OperatorEditProfile    from './pages/operator/OperatorEditProfile';
import AdminDashboard      from './pages/admin/AdminDashboard';
import UserManagement      from './pages/admin/UserManagement';
import AdminVerifications  from './pages/admin/AdminVerifications';
import AdminEquipment      from './pages/admin/AdminEquipment';
import AdminMarketplace    from './pages/admin/AdminMarketplace';
import AdminBookings       from './pages/admin/AdminBookings';
import AdminPayments       from './pages/admin/AdminPayments';
import AdminAiReports      from './pages/admin/AdminAiReports';
import AdminReviews        from './pages/admin/AdminReviews';
import AdminSupport        from './pages/admin/AdminSupport';
import AdminNotifications  from './pages/admin/AdminNotifications';
import AdminReports        from './pages/admin/AdminReports';
import AdminActivityLogs   from './pages/admin/AdminActivityLogs';
import AdminSettings       from './pages/admin/AdminSettings';
import AdminProfile        from './pages/admin/AdminProfile';

/* ── Protected Route Wrapper ── */
function ProtectedRoute({ children, allowedRoles }) {
  const { user } = useAuth();
  if (!user) return <Navigate to="/auth/select-role" replace />;
  if (allowedRoles && !allowedRoles.includes(user.role)) return <Navigate to="/" replace />;
  return children;
}

export default function App() {
  return (
    <Routes>
      {/* ═══════════════════════════════════════
          PUBLIC PAGES (No Auth Required)
         ═══════════════════════════════════════ */}
      <Route element={<PublicLayout />}>
        <Route index element={<WelcomePage />} />
        <Route path="explore" element={<ExplorePage />} />
      </Route>

      {/* ═══════════════════════════════════════
          AUTHENTICATION MODULE (Dark Premium Layout)
         ═══════════════════════════════════════ */}
      <Route element={<AuthLayout />}>
        {/* Core Auth Routes */}
        <Route path="auth/select-role"     element={<RoleSelectionPage />} />
        <Route path="auth/login"           element={<LoginPage />} />
        <Route path="auth/register"        element={<RegisterPage />} />
        <Route path="auth/forgot-password" element={<ForgotPasswordPage />} />
        <Route path="auth/verify-otp"      element={<OTPVerificationPage />} />
        <Route path="auth/reset-password"  element={<ResetPasswordPage />} />
        <Route path="auth/verify-success"  element={<VerifySuccessPage />} />

        {/* Role Specific Shortcuts */}
        <Route path="farmer/login"    element={<FarmerLogin />} />
        <Route path="farmer/register" element={<FarmerRegister />} />
        <Route path="owner/login"     element={<OwnerLogin />} />
        <Route path="owner/register"  element={<OwnerRegister />} />
        <Route path="sprayer/login"   element={<LoginPage initialRole="sprayer" />} />
        <Route path="sprayer/register" element={<RegisterPage initialRole="sprayer" />} />
        <Route path="admin/login"     element={<AdminLogin />} />
      </Route>

      {/* ═══════════════════════════════════════
          FARMER APP (Role: FARMER / SPRAYER)
         ═══════════════════════════════════════ */}
      <Route path="farmer" element={
        <ProtectedRoute allowedRoles={['FARMER', 'SPRAYER', 'ADMIN']}>
          <FarmerLayout />
        </ProtectedRoute>
      }>
        <Route path="dashboard"                 element={<FarmerDashboard />} />
        <Route path="equipment"                 element={<EquipmentSearch />} />
        <Route path="equipment/:id"             element={<EquipmentDetail />} />
        <Route path="equipment/:id/availability" element={<EquipmentAvailabilityPage />} />
        <Route path="equipment/:id/duration"    element={<RentalDurationPage />} />
        <Route path="equipment/:id/book"        element={<BookingConfirm />} />
        <Route path="marketplace"        element={<MarketplacePage />} />
        <Route path="marketplace/:id"    element={<ProductDetail />} />
        <Route path="cart"               element={<CartPage />} />
        <Route path="checkout"           element={<CheckoutPage />} />
        <Route path="payment"            element={<PaymentPage />} />
        <Route path="order-success"      element={<OrderSuccessPage />} />
        <Route path="orders"             element={<MyOrdersPage />} />
        <Route path="sprayers"           element={<SprayerServices />} />
        <Route path="sprayers/:id"       element={<SprayerDetail />} />
        <Route path="sprayers/:id/book-time" element={<ServiceBookingTimePage />} />
        <Route path="sprayers/:id/location" element={<ServiceLocationPage />} />
        <Route path="sprayers/:id/review"   element={<ServiceBookingSummaryPage />} />
        <Route path="sprayers/history"      element={<SprayerHistoryPage />} />
        <Route path="sprayers/success"      element={<ServiceBookingSuccessPage />} />
        <Route path="bookings"           element={<BookingHistory />} />
        <Route path="ai-doctor"          element={<AiDoctorHome />} />
        <Route path="ai-doctor/upload"   element={<AiDoctorUpload />} />
        <Route path="ai-doctor/result/:id" element={<AiDoctorResult />} />
        <Route path="ai-doctor/report/:id" element={<AiDoctorReport />} />
        <Route path="ai-doctor/history"  element={<AiDoctorHistory />} />
        <Route path="notifications"      element={<NotificationsPage />} />
        <Route path="messages"          element={<FarmerDashboard />} />
        <Route path="profile"            element={<FarmerProfilePage />} />
        <Route path="profile/edit"       element={<EditProfilePage />} />
        <Route path="settings"           element={<SettingsPage />} />
      </Route>

      {/* ═══════════════════════════════════════
          OWNER APP (Role: EQUIPMENT_OWNER)
         ═══════════════════════════════════════ */}
      <Route path="owner" element={
        <ProtectedRoute allowedRoles={['EQUIPMENT_OWNER', 'ADMIN']}>
          <OwnerLayout />
        </ProtectedRoute>
      }>
        <Route index element={<Navigate to="dashboard" replace />} />
        <Route path="dashboard"          element={<OwnerDashboard />} />
        <Route path="equipment"          element={<OwnerEquipment />} />
        <Route path="equipment/add"      element={<AddEquipment />} />
        <Route path="equipment/edit/:id" element={<EditEquipment />} />
        <Route path="bookings"           element={<OwnerBookings />} />
        <Route path="calendar"           element={<OwnerCalendar />} />
        <Route path="earnings"           element={<OwnerEarnings />} />
        <Route path="reviews"            element={<OwnerReviews />} />
        <Route path="notifications"      element={<OwnerNotifications />} />
        <Route path="profile"            element={<OwnerProfile />} />
        <Route path="profile/edit"       element={<OwnerEditProfile />} />
      </Route>

      {/* ═══════════════════════════════════════
          OPERATOR PORTAL
      ═══════════════════════════════════════ */}
      <Route path="operator" element={
        <ProtectedRoute allowedRoles={['SPRAYER', 'ADMIN']}>
          <OperatorLayout />
        </ProtectedRoute>
      }>
        <Route index element={<Navigate to="dashboard" replace />} />
        <Route path="dashboard"          element={<OperatorDashboard />} />
        <Route path="jobs"               element={<OperatorJobs />} />
        <Route path="jobs/:id"           element={<OperatorJobDetails />} />
        <Route path="calendar"           element={<OperatorCalendar />} />
        <Route path="earnings"           element={<OperatorEarnings />} />
        <Route path="customers"          element={<OperatorCustomers />} />
        <Route path="reviews"            element={<OperatorReviews />} />
        <Route path="notifications"      element={<OperatorNotifications />} />
        <Route path="profile"            element={<OperatorProfile />} />
        <Route path="profile/edit"       element={<OperatorEditProfile />} />
      </Route>

      {/* ═══════════════════════════════════════
          ADMIN PORTAL
         ═══════════════════════════════════════ */}
      <Route path="admin" element={
        <ProtectedRoute allowedRoles={['ADMIN']}>
          <AdminLayout />
        </ProtectedRoute>
      }>
        <Route index element={<Navigate to="dashboard" replace />} />
        <Route path="dashboard"       element={<AdminDashboard />} />
        <Route path="users"           element={<UserManagement />} />
        <Route path="verifications"   element={<AdminVerifications />} />
        <Route path="equipment"       element={<AdminEquipment />} />
        <Route path="marketplace"     element={<AdminMarketplace />} />
        <Route path="bookings"        element={<AdminBookings />} />
        <Route path="payments"        element={<AdminPayments />} />
        <Route path="ai-reports"      element={<AdminAiReports />} />
        <Route path="reviews"         element={<AdminReviews />} />
        <Route path="support"         element={<AdminSupport />} />
        <Route path="notifications"   element={<AdminNotifications />} />
        <Route path="reports"         element={<AdminReports />} />
        <Route path="activity-logs"   element={<AdminActivityLogs />} />
        <Route path="settings"        element={<AdminSettings />} />
        <Route path="profile"         element={<AdminProfile />} />
      </Route>

      {/* ── Catch-all → back to Welcome ── */}
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { FiActivity, FiDollarSign, FiBell, FiZap, FiCloud, FiSun } from 'react-icons/fi';
import api from '../services/api';

/* animated counter hook */
function useCounter(target, duration = 1200) {
  const [val, setVal] = useState(0);
  useEffect(() => {
    let start = 0;
    const step = Math.ceil(target / (duration / 16));
    const timer = setInterval(() => {
      start += step;
      if (start >= target) { setVal(target); clearInterval(timer); }
      else setVal(start);
    }, 16);
    return () => clearInterval(timer);
  }, [target]);
  return val;
}

const DIAGNOSES = [
  { disease: 'Rice Blast (సారి తెగులు)', medicine: 'Tricyclazole 75% WP — 0.6 g/litre', status: 'Critical', color: '#dc2626', bg: '#fef2f2' },
  { disease: 'Bacterial Leaf Blight (ఆకు ఎండు)', medicine: 'Copper Oxychloride 3g + Streptocycline 0.1g/litre', status: 'Moderate', color: '#b45309', bg: '#fef9c3' },
  { disease: 'Healthy Leaf (ఆరోగ్యకరమైన)', medicine: 'No treatment needed. Maintain regular irrigation.', status: 'Healthy', color: '#16a34a', bg: '#dcfce7' },
];

const WEATHER_DATA = {
  temp: '32°C',
  condition: 'Clear & Sunny',
  humidity: '68%',
  wind: '12 km/h',
  advisory: 'Excellent conditions for pesticide spraying today. Avoid irrigation after 4 PM.',
};

const stagger = {
  container: { animate: { transition: { staggerChildren: 0.09 } } },
  item: {
    initial: { opacity: 0, y: 18 },
    animate: { opacity: 1, y: 0, transition: { duration: 0.4, ease: [0.16, 1, 0.3, 1] } },
  },
};

export default function Dashboard({ user }) {
  const [stats, setStats] = useState({ activeBookingsCount: 0, totalExpenses: 0, totalEarnings: 0 });
  const [notifications, setNotifications] = useState([]);
  const [leaf, setLeaf] = useState(null);
  const [scanning, setScanning] = useState(false);
  const [result, setResult] = useState(null);
  const [progress, setProgress] = useState(0);

  const activeCount = useCounter(stats.activeBookingsCount);
  const moneyCount = useCounter(stats.totalExpenses || stats.totalEarnings);

  useEffect(() => {
    (async () => {
      try {
        const ep = user.role === 'EQUIPMENT_OWNER' ? '/dashboards/owner' : '/dashboards/farmer';
        const res = await api.get(ep);
        if (res.success) {
          setStats(res.data);
          setNotifications(res.data.recentNotifications || []);
        }
      } catch (_) {}
    })();
  }, []);

  const handleScan = () => {
    if (!leaf) return;
    setScanning(true); setResult(null); setProgress(0);
    const interval = setInterval(() => {
      setProgress(p => {
        if (p >= 100) { clearInterval(interval); return 100; }
        return p + 2;
      });
    }, 40);
    setTimeout(() => {
      setScanning(false);
      setResult(DIAGNOSES[Math.floor(Math.random() * DIAGNOSES.length)]);
    }, 2200);
  };

  return (
    <motion.div variants={stagger.container} initial="initial" animate="animate" className="flex flex-col gap-6">

      {/* ── Welcome Banner ── */}
      <motion.div variants={stagger.item}
        className="relative rounded-2xl overflow-hidden p-7 text-white"
        style={{ background: 'linear-gradient(135deg, #000 0%, #18181b 60%, #16a34a 200%)' }}
      >
        <div className="relative z-10 flex flex-col sm:flex-row justify-between gap-4">
          <div>
            <p className="text-xs font-semibold mb-1 uppercase tracking-wider" style={{ color: '#a1a1aa' }}>Welcome back</p>
            <h1 className="text-2xl font-black tracking-tight">{user.fullName}</h1>
            <p className="text-sm mt-1" style={{ color: '#a1a1aa' }}>{user.village}, {user.district}</p>
          </div>
          <div className="flex items-start gap-3">
            <div className="rounded-xl px-4 py-3 text-center" style={{ background: 'rgba(255,255,255,0.07)', border: '1px solid rgba(255,255,255,0.1)' }}>
              <FiSun size={18} className="mx-auto mb-1" style={{ color: '#fbbf24' }} />
              <p className="text-lg font-black">{WEATHER_DATA.temp}</p>
              <p className="text-[10px] font-medium" style={{ color: '#a1a1aa' }}>{WEATHER_DATA.condition}</p>
            </div>
            <div className="rounded-xl px-4 py-3" style={{ background: 'rgba(255,255,255,0.07)', border: '1px solid rgba(255,255,255,0.1)' }}>
              <p className="text-[10px] font-bold uppercase tracking-wider mb-1" style={{ color: '#6b7280' }}>Humidity</p>
              <p className="text-base font-black">{WEATHER_DATA.humidity}</p>
              <p className="text-[10px] font-bold uppercase tracking-wider mt-1" style={{ color: '#6b7280' }}>Wind</p>
              <p className="text-base font-black">{WEATHER_DATA.wind}</p>
            </div>
          </div>
        </div>
      </motion.div>

      {/* ── Advisory ── */}
      <motion.div variants={stagger.item}
        className="flex items-start gap-3 rounded-xl p-4"
        style={{ background: '#f0fdf4', border: '1px solid #bbf7d0' }}
      >
        <FiZap size={16} style={{ color: '#16a34a', flexShrink: 0, marginTop: 2 }} />
        <p className="text-sm font-semibold" style={{ color: '#15803d' }}>
          <strong>Today's Advisory:</strong> {WEATHER_DATA.advisory}
        </p>
      </motion.div>

      {/* ── Stat Cards ── */}
      <motion.div variants={stagger.item} className="grid grid-cols-1 sm:grid-cols-3 gap-5">
        {[
          { label: 'Active Bookings', val: activeCount, icon: FiActivity, color: '#000', prefix: '' },
          { label: user.role === 'EQUIPMENT_OWNER' ? 'Total Earnings' : 'Total Expenses', val: moneyCount, icon: FiDollarSign, color: '#16a34a', prefix: '₹' },
          { label: 'Notifications', val: notifications.length, icon: FiBell, color: '#b45309', prefix: '' },
        ].map((s) => (
          <motion.div key={s.label} className="stat-card" whileHover={{ scale: 1.01 }}>
            <div className="flex items-start justify-between mb-4">
              <p className="text-xs font-bold uppercase tracking-wider" style={{ color: '#a1a1aa' }}>{s.label}</p>
              <div className="w-9 h-9 rounded-xl flex items-center justify-center"
                style={{ background: s.color === '#000' ? '#000' : s.color === '#16a34a' ? '#dcfce7' : '#fef3c7' }}>
                <s.icon size={15} style={{ color: s.color === '#000' ? '#fff' : s.color }} />
              </div>
            </div>
            <p className="text-3xl font-black" style={{ color: '#000' }}>{s.prefix}{s.val}</p>
          </motion.div>
        ))}
      </motion.div>

      {/* ── Main Grid: Plant Doctor + Notifications ── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* Plant Doctor */}
        <motion.div variants={stagger.item} className="card p-6 flex flex-col">
          <div className="flex items-center gap-3 mb-5">
            <div className="w-10 h-10 rounded-xl flex items-center justify-center text-xl" style={{ background: '#f0fdf4' }}>🩺</div>
            <div>
              <h2 className="font-black text-base tracking-tight">Plant Doctor</h2>
              <p className="text-xs" style={{ color: '#a1a1aa' }}>AI-powered crop disease detection</p>
            </div>
          </div>

          {/* Upload Zone */}
          {!leaf && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="flex-1 rounded-xl flex flex-col items-center justify-center gap-4 py-10 cursor-pointer"
              style={{ border: '2px dashed #e4e4e7', background: '#fafafa' }}
              onClick={() => setLeaf('sample')}
              whileHover={{ borderColor: '#000', background: '#f4f4f5' }}
            >
              <motion.div animate={{ y: [0, -6, 0] }} transition={{ duration: 2.5, repeat: Infinity }}>
                <span className="text-5xl">🍃</span>
              </motion.div>
              <div className="text-center">
                <p className="font-bold text-sm">Select a leaf sample</p>
                <p className="text-xs mt-1" style={{ color: '#a1a1aa' }}>Tap to load sample or upload image</p>
              </div>
              <div className="flex gap-2">
                {['Paddy Leaf', 'Tomato Leaf', 'Wheat Leaf'].map(l => (
                  <button key={l} onClick={e => { e.stopPropagation(); setLeaf(l); }}
                    className="btn btn-ghost btn-sm">{l}</button>
                ))}
              </div>
            </motion.div>
          )}

          {leaf && !result && (
            <div className="flex-1 flex flex-col gap-4">
              <div className="rounded-xl p-4 flex items-center gap-4" style={{ background: '#f4f4f5' }}>
                <span className="text-4xl">🍃</span>
                <div>
                  <p className="font-bold text-sm">{leaf}</p>
                  <p className="text-xs" style={{ color: '#a1a1aa' }}>Ready for analysis</p>
                </div>
              </div>

              {scanning ? (
                <div className="space-y-3">
                  <div className="flex items-center justify-between text-xs font-semibold" style={{ color: '#52525b' }}>
                    <span>⚡ Running deep-learning scan...</span>
                    <span>{progress}%</span>
                  </div>
                  <div className="h-2 rounded-full overflow-hidden" style={{ background: '#e4e4e7' }}>
                    <motion.div
                      className="h-full rounded-full"
                      style={{ background: '#000', width: `${progress}%` }}
                    />
                  </div>
                  <p className="text-xs text-center animate-pulse" style={{ color: '#a1a1aa' }}>
                    Analyzing chlorophyll patterns, lesions, and discolorations...
                  </p>
                </div>
              ) : (
                <div className="flex gap-3">
                  <button onClick={handleScan} className="btn btn-black flex-1">Start Diagnosis</button>
                  <button onClick={() => setLeaf(null)} className="btn btn-ghost">Clear</button>
                </div>
              )}
            </div>
          )}

          {result && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              className="flex-1 rounded-xl p-5"
              style={{ background: result.bg, border: `1.5px solid ${result.color}22` }}
            >
              <div className="flex items-start justify-between gap-3 mb-3">
                <h3 className="font-black text-sm">{result.disease}</h3>
                <span className="badge flex-shrink-0" style={{ background: result.bg, color: result.color, border: `1px solid ${result.color}44` }}>
                  {result.status}
                </span>
              </div>
              <div className="divider" style={{ margin: '12px 0' }} />
              <p className="text-xs font-semibold mb-1" style={{ color: '#52525b' }}>💊 Recommended Treatment</p>
              <p className="text-sm font-bold" style={{ color: result.color }}>{result.medicine}</p>
              <button onClick={() => { setLeaf(null); setResult(null); }} className="btn btn-ghost btn-sm mt-4">
                New Scan
              </button>
            </motion.div>
          )}
        </motion.div>

        {/* Notifications */}
        <motion.div variants={stagger.item} className="card p-6 flex flex-col">
          <div className="flex items-center justify-between mb-5">
            <h2 className="font-black text-base tracking-tight">Notifications</h2>
            {notifications.length > 0 && (
              <span className="badge badge-black">{notifications.length}</span>
            )}
          </div>

          {notifications.length === 0 ? (
            <div className="flex-1 flex flex-col items-center justify-center gap-3 py-12" style={{ color: '#a1a1aa' }}>
              <span className="text-4xl">🔔</span>
