const SEPARATOR_MOTION = {
  initial: { opacity: 0, scale: 0.8 },
  animate: { opacity: 1, scale: 1 },
  exit: { opacity: 0, scale: 0.8 },
  transition: { duration: 0.15, ease: [0.4, 0, 0.2, 1] },
};

/** Separator character mapping. */
const SEPARATOR_CHARS = {
  slash: '/',
  chevron: '›',
  arrow: '→',
  dot: '•',
  hyphen: '-',
  pipe: '|',
};

