                      <Stop offset="5%" stopColor={color} stopOpacity={0.8} />
                      <Stop offset="95%" stopColor={color} stopOpacity={0.1} />
                    </LinearGradient>
                  );
                })}
              </Defs>
            )}

            {/* Grid */}
            {grid && <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />}

            {/* X-Axis */}
            <XAxis
              dataKey="name"
              label={xAxisLabel ? { value: xAxisLabel, position: 'insideBottom', offset: -5 } : undefined}
              tick={{ fontSize: 12, fill: '#6b7280' }}
              axisLine={{ stroke: '#d1d5db' }}
              tickLine={{ stroke: '#d1d5db' }}
            />

            {/* Y-Axis */}
            <YAxis
              label={yAxisLabel ? { value: yAxisLabel, angle: -90, position: 'insideLeft' } : undefined}
              tick={{ fontSize: 12, fill: '#6b7280' }}
              axisLine={{ stroke: '#d1d5db' }}
              tickLine={{ stroke: '#d1d5db' }}
            />

            {/* Tooltip */}
            <Tooltip
              contentStyle={{
                backgroundColor: 'white',
                border: '1px solid #e5e7eb',
                borderRadius: '8px',
                padding: '8px 12px',
              }}
              labelStyle={{ fontWeight: 600, color: '#1f2937' }}
              itemStyle={{ color: '#374151' }}
            />

            {/* Legend */}
            <Legend
              wrapperStyle={{ paddingTop: '10px' }}
              iconType="square"
            />

            {/* Areas */}
            {chartSeries.map((serie, index) => {
              const color = serie.color || getColor(index);
              const fillColor = gradient ? `url(#${getGradientId(index)})` : color;

              return (
                <Area
                  key={serie.dataKey || index}
                  type="monotone"
                  dataKey={serie.dataKey}
                  name={serie.name}
                  stroke={color}
                  strokeWidth={2}
                  fill={fillColor}
                  stackId={stacked ? 'stack' : undefined}
                  dot={{ r: 3, strokeWidth: 1 }}
                  activeDot={{ r: 5, strokeWidth: 2 }}
                  animationDuration={animation === 'none' ? 0 : 700}
                  animationEasing="ease-out"
                  isAnimationActive={animation !== 'none'}
                />
              );
            })}
          </RechartsAreaChart>
        </ResponsiveContainer>
      </div>
    );
  }),
);

AreaChart.displayName = 'AreaChart';

AreaChart.propTypes = {
  /** Chart data. */
  data: PropTypes.arrayOf(
    PropTypes.oneOfType([
      PropTypes.object,
      PropTypes.number,
      PropTypes.string,
    ]),
  ),
  /** Series configuration. */
  series: PropTypes.arrayOf(
    PropTypes.shape({
      name: PropTypes.string,
      dataKey: PropTypes.string,
      color: PropTypes.string,
    }),
  ),
  /** Data key for values. */
  dataKey: PropTypes.string,
  /** Name key for labels. */
  nameKey: PropTypes.string,
  /** X-axis label. */
  xAxisLabel: PropTypes.string,
  /** Y-axis label. */
  yAxisLabel: PropTypes.string,
  /** Color palette. */
  colors: PropTypes.oneOf(['default', 'pastel', 'vibrant', 'dark', 'gradient']),
  /** Animation type. */
  animation: PropTypes.oneOf(['grow', 'fade', 'slide', 'scale', 'none']),
  /** Whether to show grid. */
  grid: PropTypes.bool,
  /** Stacked chart. */
  stacked: PropTypes.bool,
  /** Whether to show gradient fill. */
  gradient: PropTypes.bool,
  /** Disabled state. */
  disabled: PropTypes.bool,
  /** Loading state. */
  loading: PropTypes.bool,
  /** Responsive overrides. */
  responsive: PropTypes.shape({
    xs: PropTypes.string,
    sm: PropTypes.string,
    md: PropTypes.string,
    lg: PropTypes.string,
    xl: PropTypes.string,
  }),
  /** Additional CSS classes. */
  className: PropTypes.string,
};

export default AreaChart;

