  xs: 'h-6',
  sm: 'h-7',
  md: 'h-8',
  lg: 'h-9',
  xl: 'h-10',
};

/** Width presets for skeleton rows. */
const SKELETON_WIDTHS = ['w-3/4', 'w-full', 'w-5/6', 'w-2/3', 'w-1/2'];

/** Default number of rows. */
const DEFAULT_ROWS = 4;

/** Motion variants for loader animation. */
const LOADER_MOTION = {
  initial: { opacity: 0, scale: 0.95 },
  animate: { opacity: 1, scale: 1 },
  transition: { duration: 0.2, ease: [0.4, 0, 0.2, 1] },
};

/* ---------------------------------- */
/* Component                          */
/* ---------------------------------- */

/**
 * DropdownLoader – a skeleton loader for dropdowns.
 *
 * @component
 * @example
 * <DropdownLoader size="md" variant="shimmer" rows={3} />
 */
const DropdownLoader = memo(
  forwardRef(function DropdownLoader(
    {
      size = DROPDOWN_DEFAULTS.size,
      variant = 'shimmer',
      animated = true,
      rows = DEFAULT_ROWS,
      disabled = false,
      responsive,
      className = '',
