const FileUploadDropzone = memo(
  forwardRef(function FileUploadDropzone(
    {
      children,
      htmlFor,
      label,
      icon,
      size = FILE_UPLOAD_DEFAULTS.size,
      variant = FILE_UPLOAD_DEFAULTS.variant,
      disabled = false,
