      return null;
    }, [maxSize]);

    // Helper text for max files.
    const filesText = useMemo(() => {
      if (maxFiles > 1) {
        return `Max files: ${maxFiles}`;
      }
      return null;
    }, [maxFiles]);

    return (
      <motion.div
        ref={ref}
        className={uploadClasses}
        onClick={handleClick}
        onDragEnter={handleDragEnter}
        onDragLeave={handleDragLeave}
        onDragOver={handleDragOver}
        onDrop={handleDrop}
        {...motionProps}
        {...ariaProps}
        {...dataAttributes}
        {...rest}
