  sm: 'min-h-[100px]',
  md: 'min-h-[140px]',
  lg: 'min-h-[180px]',
  xl: 'min-h-[220px]',
};

/** Icon skeleton size mapping. */
const ICON_SKELETON_SIZES = {
  xs: 'h-8 w-8',
  sm: 'h-10 w-10',
  md: 'h-12 w-12',
  lg: 'h-14 w-14',
  xl: 'h-16 w-16',
