        'bg-gray-100 border-2 border-dashed border-gray-200 rounded-lg',
        fileUploadSize,
        sizeConfig.padding,
        sizeConfig.gap,
        isAnimated && variant === 'pulse' && 'animate-pulse',
      );
      return base;
    }, [fileUploadSize, sizeConfig.padding, sizeConfig.gap, isAnimated, variant]);

