 * SkeletonContainer – the main skeleton wrapper with layout and styling.
 *
 * @component
 * @example
 * <SkeletonContainer>
 *   <SkeletonText />
 *   <SkeletonAvatar />
 * </SkeletonContainer>
 *
 * @example
 * <SkeletonContainer layout="grid" columns={3} gap="4">
 *   <SkeletonCard />
 *   <SkeletonCard />
 *   <SkeletonCard />
 * </SkeletonContainer>
 */
const SkeletonContainer = memo(
  forwardRef(function SkeletonContainer(
    {
      children,
      layout = DEFAULT_LAYOUT,
      orientation = DEFAULT_ORIENTATION,
      columns = 1,
      gap = 'gap-2',
      align = 'start',
      justify = 'start',
      wrap = false,
      disabled = false,
      loading = true,
      responsive,
      className = '',
      role = 'status',
      'aria-label': ariaLabel = 'Loading',
      ...rest
    },
    ref,
  ) {
    const prefersReducedMotion = useReducedMotion();

    // Resolve defaults.
    const resolved = useMemo(
      () =>
        resolveDefaultProps({
          disabled,
          loading,
        }),
      [disabled, loading],
    );

    // Layout classes.
    const layoutClass = useMemo(
      () => LAYOUT_MAP[layout] || LAYOUT_MAP[DEFAULT_LAYOUT],
      [layout],
    );

    // Orientation classes.
    const orientationClass = useMemo(() => {
      if (layout === 'grid') return '';
      return ORIENTATION_MAP[orientation] || ORIENTATION_MAP[DEFAULT_ORIENTATION];
    }, [layout, orientation]);

    // Grid columns class.
    const columnsClass = useMemo(() => {
      if (layout !== 'grid') return '';
      return GRID_COLUMNS[columns] || GRID_COLUMNS[1];
    }, [layout, columns]);

    // Alignment classes.
    const alignClass = useMemo(() => {
      const map = {
        start: 'items-start',
        center: 'items-center',
        end: 'items-end',
        stretch: 'items-stretch',
      };
      return map[align] || map.start;
    }, [align]);

    const justifyClass = useMemo(() => {
      const map = {
        start: 'justify-start',
        center: 'justify-center',
        end: 'justify-end',
        between: 'justify-between',
        around: 'justify-around',
        evenly: 'justify-evenly',
      };
      return map[justify] || map.start;
    }, [justify]);

    // Wrap class.
    const wrapClass = wrap ? 'flex-wrap' : '';

    // Container classes.
    const containerClasses = useMemo(
      () =>
        getSkeletonContainerClasses({
          className,
          disabled: resolved.disabled,
          loading: resolved.loading,
          orientation,
        }),
      [className, resolved.disabled, resolved.loading, orientation],
    );

    // Responsive overrides.
    const responsiveClasses = useMemo(
      () => (responsive ? resolveResponsiveClasses(responsive) : ''),
      [responsive],
    );

    const finalClasses = useMemo(
      () =>
        mergeClasses(
          containerClasses,
          layoutClass,
          orientationClass,
          columnsClass,
          gap,
          alignClass,
          justifyClass,
          wrapClass,
          responsiveClasses,
        ),
      [
        containerClasses,
        layoutClass,
        orientationClass,
        columnsClass,
        gap,
        alignClass,
        justifyClass,
        wrapClass,
        responsiveClasses,
      ],
    );

    // Motion props - respect reduced motion.
    const motionProps = useMemo(() => {
      if (prefersReducedMotion) {
        return { initial: false, animate: true };
      }
      return CONTAINER_MOTION;
    }, [prefersReducedMotion]);

    // Accessibility attributes.
    const ariaProps = useMemo(
      () => ({
        role,
        'aria-label': ariaLabel,
        'aria-busy': resolved.loading || undefined,
        'aria-disabled': resolved.disabled || undefined,
        'data-layout': layout,
        'data-orientation': orientation,
        'data-columns': columns,
      }),
      [role, ariaLabel, resolved.loading, resolved.disabled, layout, orientation, columns],
    );

    // If not loading, render nothing.
    if (!resolved.loading) {
      return null;
    }

    return (
      <motion.div
        ref={ref}
        className={finalClasses}
        {...motionProps}
        {...ariaProps}
        {...rest}
      >
        {children}
      </motion.div>
    );
  }),
);

SkeletonContainer.displayName = 'SkeletonContainer';

SkeletonContainer.propTypes = {
  /** Skeleton elements. */
  children: PropTypes.node,
  /** Layout type. */
  layout: PropTypes.oneOf(['flex', 'grid', 'inline']),
  /** Orientation for flex layouts. */
  orientation: PropTypes.oneOf(['horizontal', 'vertical']),
  /** Number of grid columns. */
  columns: PropTypes.oneOf([1, 2, 3, 4, 5, 6, 8, 12]),
  /** Gap between elements. */
  gap: PropTypes.string,
  /** Alignment on cross axis. */
  align: PropTypes.oneOf(['start', 'center', 'end', 'stretch']),
  /** Alignment on main axis. */
  justify: PropTypes.oneOf(['start', 'center', 'end', 'between', 'around', 'evenly']),
  /** Whether to wrap elements. */
  wrap: PropTypes.bool,
  /** Disabled state. */
  disabled: PropTypes.bool,
  /** Loading state. */
  loading: PropTypes.bool,
  /** Responsive overrides. */
  responsive: PropTypes.shape({
    xs: PropTypes.string,
    sm: PropTypes.string,
    md: PropTypes.string,
    lg: PropTypes.string,
    xl: PropTypes.string,
  }),
  /** Additional CSS classes. */
  className: PropTypes.string,
  /** ARIA role. */
  role: PropTypes.string,
  /** Accessible label. */
  'aria-label': PropTypes.string,
};

export default SkeletonContainer;

/**
 * KisanO Design System — Skeleton Package
 * SkeletonText
 *
 * A text skeleton loader component. Renders placeholder text lines
 * with variable widths, pulse or shimmer animations, and responsive support.
 *
 * Single Responsibility: Render text skeleton placeholders.
 * Does not manage skeleton state or business logic.
 *
 * @module components/ui/Skeleton/SkeletonText
 */

import { forwardRef, memo, useMemo } from 'react';
import PropTypes from 'prop-types';
import { motion, useReducedMotion } from 'framer-motion';

import {
  SKELETON_DEFAULTS,
} from './skeletonVariants';
import {
  mergeClasses,
  resolveResponsiveClasses,
  getSkeletonTextClasses,
} from './skeletonUtils';

/* ---------------------------------- */
/* Component-specific tokens          */
/* ---------------------------------- */

/** Motion variants for text animation. */
const TEXT_MOTION = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  transition: { duration: 0.15, ease: [0.4, 0, 0.2, 1] },
};

/** Staggered animation variants for multiple lines. */
const STAGGER_MOTION = {
  initial: { opacity: 0, y: -4 },
  animate: { opacity: 1, y: 0 },
  transition: { duration: 0.15, staggerChildren: 0.05 },
};

/** Width presets for text lines. */
const WIDTH_PRESETS = {
  full: 'w-full',
  '3/4': 'w-3/4',
  '2/3': 'w-2/3',
  '1/2': 'w-1/2',
  '1/3': 'w-1/3',
  '1/4': 'w-1/4',
  auto: 'w-auto',
};

/** Default lines when not provided. */
const DEFAULT_LINES = 1;

/** Default width when not provided. */
const DEFAULT_WIDTH = 'full';

/* ---------------------------------- */
/* Component                          */
/* ---------------------------------- */

/**
 * SkeletonText – a text skeleton loader.
 *
 * @component
 * @example
 * <SkeletonText lines={3} />
 *
 * @example
 * <SkeletonText lines={2} width="3/4" variant="primary" animation="shimmer" />
 */
const SkeletonText = memo(
  forwardRef(function SkeletonText(
    {
      children,
      lines = DEFAULT_LINES,
      width = DEFAULT_WIDTH,
      size = SKELETON_DEFAULTS.size,
      variant = SKELETON_DEFAULTS.variant,
      radius = SKELETON_DEFAULTS.radius,
      animation = SKELETON_DEFAULTS.animation,
      spacing = 'gap-2',
      lastLineWidth = '3/4',
      disabled = false,
      loading = true,
      responsive,
      className = '',
      ...rest
    },
    ref,
  ) {
    const prefersReducedMotion = useReducedMotion();

    // Determine if loading.
    const isLoading = loading && !disabled;

    // Get width class.
    const widthClass = useMemo(
      () => WIDTH_PRESETS[width] || WIDTH_PRESETS[DEFAULT_WIDTH],
      [width],
    );

    // Get last line width.
    const lastWidthClass = useMemo(
      () => WIDTH_PRESETS[lastLineWidth] || WIDTH_PRESETS['3/4'],
      [lastLineWidth],
    );

    // Responsive overrides.
    const responsiveClasses = useMemo(
      () => (responsive ? resolveResponsiveClasses(responsive) : ''),
      [responsive],
    );

    // Container classes.
    const containerClasses = useMemo(() => {
      const base = mergeClasses(
        'flex flex-col',
        spacing,
        disabled && 'opacity-50 cursor-not-allowed',
        className,
      );
      return mergeClasses(base, responsiveClasses);
    }, [spacing, disabled, className, responsiveClasses]);

    // Generate line classes.
    const lineClasses = useMemo(() => {
      const base = getSkeletonTextClasses({
        size,
        variant,
        radius,
        animation,
        className: '',
        disabled,
        loading: isLoading,
      });

      const linesArray = [];
      for (let i = 0; i < lines; i++) {
        const isLast = i === lines - 1;
        const lineWidth = isLast ? lastWidthClass : widthClass;
        linesArray.push(
          mergeClasses(
            base,
            lineWidth,
            isLast && lastLineWidth !== width ? 'w-[var(--last-width)]' : '',
          ),
        );
      }
      return linesArray;
    }, [size, variant, radius, animation, disabled, isLoading, lines, widthClass, lastWidthClass]);

    // Motion props - respect reduced motion.
    const motionProps = useMemo(() => {
      if (prefersReducedMotion) {
        return { initial: false, animate: true };
      }
      return lines > 1 ? STAGGER_MOTION : TEXT_MOTION;
    }, [prefersReducedMotion, lines]);

    // If not loading, render nothing.
    if (!isLoading) {
      return null;
    }

    // Render children if provided.
    if (children) {
      return <span ref={ref} className={containerClasses}>{children}</span>;
    }

    // Render text lines.
    return (
      <div ref={ref} className={containerClasses} {...rest}>
        {lineClasses.map((lineClass, index) => (
          <motion.div
            key={index}
            className={lineClass}
            {...motionProps}
          />
        ))}
      </div>
    );
  }),
);

SkeletonText.displayName = 'SkeletonText';

SkeletonText.propTypes = {
  /** Custom children (overrides default rendering). */
  children: PropTypes.node,
  /** Number of text lines. */
  lines: PropTypes.number,
  /** Width of text lines. */
  width: PropTypes.oneOf(['full', '3/4', '2/3', '1/2', '1/3', '1/4', 'auto']),
  /** Size preset. */
  size: PropTypes.oneOf(['xs', 'sm', 'md', 'lg', 'xl']),
  /** Visual variant. */
  variant: PropTypes.oneOf(['default', 'light', 'dark', 'primary']),
  /** Border radius override. */
  radius: PropTypes.oneOf(['none', 'sm', 'md', 'lg', 'xl', '2xl', 'full']),
  /** Animation type. */
  animation: PropTypes.oneOf(['pulse', 'shimmer', 'wave', 'none']),
  /** Spacing between lines. */
  spacing: PropTypes.string,
  /** Width of the last line. */
  lastLineWidth: PropTypes.oneOf(['full', '3/4', '2/3', '1/2', '1/3', '1/4', 'auto']),
  /** Disabled state. */
  disabled: PropTypes.bool,
  /** Loading state. */
  loading: PropTypes.bool,
  /** Responsive overrides. */
  responsive: PropTypes.shape({
    xs: PropTypes.string,
    sm: PropTypes.string,
    md: PropTypes.string,
    lg: PropTypes.string,
    xl: PropTypes.string,
  }),
  /** Additional CSS classes. */
  className: PropTypes.string,
};

export default SkeletonText;

/**
 * KisanO Design System — Skeleton Package
 * Skeleton Utilities
 *
 * Production-ready utility functions for the Skeleton package.
 * Contains only pure utility functions based on the existing skeletonVariants.js tokens.
 *
 * Single Responsibility: This module only provides utility functions
 * for skeleton styling, validation, and composition - no design tokens or React components.
 *
 * @module components/ui/Skeleton/skeletonUtils
 */

import {
  SKELETON_VARIANTS,
  SKELETON_SIZES,
  SKELETON_RADIUS,
  SKELETON_ANIMATIONS,
  SKELETON_DEFAULTS,
  getSkeletonVariant,
  getSkeletonSize,
  getSkeletonRadius,
  getSkeletonAnimation,
} from './skeletonVariants';

/* ---------------------------------- */
/* Core Utility Functions             */
/* ---------------------------------- */

/**
 * Merges an arbitrary list of class values into a single class string.
 * - Falsy values (null, undefined, false, '') are ignored.
 * - Whitespace is normalized.
 * - Duplicate class names are removed (first occurrence wins).
 *
 * @param {...(string|false|null|undefined)} classes - Class values to merge.
 * @returns {string} A single, de-duplicated class string.
 *
 * @example
 * mergeClasses('p-4', isError && 'border-red-500', undefined)
 * // => 'p-4 border-red-500'
 */
export function mergeClasses(...classes) {
  const seen = new Set();
  const tokens = classes
    .filter(Boolean)
    .join(' ')
    .split(/\s+/)
    .filter((token) => token && !seen.has(token));

  for (const token of tokens) {
    seen.add(token);
  }
  return tokens.join(' ');
}

/**
 * Resolves responsive class overrides into a single class string.
 *
 * @param {Object} responsive - Responsive class map.
 * @param {string} [responsive.xs] - Extra small classes.
 * @param {string} [responsive.sm] - Small classes.
 * @param {string} [responsive.md] - Medium classes.
 * @param {string} [responsive.lg] - Large classes.
 * @param {string} [responsive.xl] - Extra large classes.
 * @returns {string} Merged responsive classes.
 */
export function resolveResponsiveClasses(responsive = {}) {
  const { xs, sm, md, lg, xl } = responsive;
  return mergeClasses(
    xs || '',
    sm ? `sm:${sm}` : '',
    md ? `md:${md}` : '',
    lg ? `lg:${lg}` : '',
    xl ? `xl:${xl}` : '',
  );
}

/**
 * Resolves default props for skeleton components.
 *
 * @param {Object} props - Component props.
 * @param {string} [props.variant] - Skeleton variant.
 * @param {string} [props.size] - Skeleton size.
 * @param {string} [props.radius] - Border radius.
 * @param {string} [props.animation] - Animation type.
 * @param {boolean} [props.disabled] - Disabled state.
 * @param {boolean} [props.loading] - Loading state.
 * @returns {Object} Resolved props with defaults applied.
 */
export function resolveDefaultProps({
  variant = SKELETON_DEFAULTS.variant,
  size = SKELETON_DEFAULTS.size,
  radius = SKELETON_DEFAULTS.radius,
  animation = SKELETON_DEFAULTS.animation,
  disabled = SKELETON_DEFAULTS.disabled,
  loading = SKELETON_DEFAULTS.loading,
}) {
  return {
    variant: SKELETON_VARIANTS[variant] ? variant : SKELETON_DEFAULTS.variant,
    size: SKELETON_SIZES[size] ? size : SKELETON_DEFAULTS.size,
    radius: SKELETON_RADIUS[radius] ? radius : SKELETON_DEFAULTS.radius,
    animation: SKELETON_ANIMATIONS[animation] ? animation : SKELETON_DEFAULTS.animation,
    disabled,
    loading,
  };
}

/* ---------------------------------- */
/* Component Class Builders           */
/* ---------------------------------- */

/**
 * Gets complete skeleton classes based on options.
 *
 * @param {Object} options - Skeleton options.
 * @param {string} [options.variant] - Skeleton variant.
 * @param {string} [options.size] - Skeleton size.
 * @param {string} [options.radius] - Border radius.
 * @param {string} [options.animation] - Animation type.
 * @param {string} [options.className] - Additional classes.
 * @param {boolean} [options.disabled] - Disabled state.
 * @param {boolean} [options.loading] - Loading state.
 * @param {boolean} [options.circular] - Circular skeleton.
 * @returns {string} Merged skeleton classes.
 */
export function getSkeletonClasses({
  variant = SKELETON_DEFAULTS.variant,
  size = SKELETON_DEFAULTS.size,
  radius = SKELETON_DEFAULTS.radius,
  animation = SKELETON_DEFAULTS.animation,
  className = '',
  disabled = false,
  loading = true,
  circular = false,
}) {
  const variantConfig = getSkeletonVariant(variant);
  const sizeConfig = getSkeletonSize(size);
  const animationConfig = getSkeletonAnimation(animation);

  const baseClasses = mergeClasses(
    'relative overflow-hidden',
    variantConfig.background,
    sizeConfig.height,
    circular ? sizeConfig.width : 'w-full',
    getSkeletonRadius(radius),
    animationConfig.transition,
    disabled && 'opacity-50 cursor-not-allowed',
    loading ? animationConfig.animation : '',
    circular && `aspect-square ${sizeConfig.width}`,
    className,
  );

  return baseClasses;
}

/**
 * Gets container classes for skeleton wrapper.
 *
 * @param {Object} options - Container options.
 * @param {string} [options.className] - Additional classes.
 * @param {boolean} [options.disabled] - Disabled state.
 * @param {boolean} [options.loading] - Loading state.
 * @param {string} [options.orientation] - Orientation.
 * @returns {string} Merged container classes.
 */
export function getSkeletonContainerClasses({
  className = '',
  disabled = false,
  loading = false,
  orientation = 'horizontal',
}) {
  const orientationMap = {
    horizontal: 'flex flex-row',
    vertical: 'flex flex-col',
  };

  return mergeClasses(
    orientationMap[orientation] || orientationMap.horizontal,
    'gap-2',
    disabled && 'opacity-50 cursor-not-allowed',
    loading && 'opacity-70',
    className,
  );
}

/**
 * Gets text skeleton classes.
 *
 * @param {Object} options - Text options.
 * @param {string} [options.size] - Skeleton size.
 * @param {string} [options.variant] - Skeleton variant.
 * @param {string} [options.radius] - Border radius.
 * @param {string} [options.animation] - Animation type.
 * @param {string} [options.className] - Additional classes.
 * @param {boolean} [options.disabled] - Disabled state.
 * @param {boolean} [options.loading] - Loading state.
 * @param {string} [options.width] - Custom width.
 * @param {number} [options.lines] - Number of lines.
 * @returns {string} Merged text skeleton classes.
 */
export function getSkeletonTextClasses({
  size = SKELETON_DEFAULTS.size,
  variant = SKELETON_DEFAULTS.variant,
  radius = SKELETON_DEFAULTS.radius,
  animation = SKELETON_DEFAULTS.animation,
  className = '',
  disabled = false,
  loading = true,
  width = '',
  lines = 1,
}) {
  const sizeConfig = getSkeletonSize(size);
  const variantConfig = getSkeletonVariant(variant);
  const animationConfig = getSkeletonAnimation(animation);

  const baseClasses = mergeClasses(
    'relative overflow-hidden',
    variantConfig.background,
    sizeConfig.height,
    width || 'w-full',
    getSkeletonRadius(radius),
    animationConfig.transition,
    disabled && 'opacity-50 cursor-not-allowed',
    loading ? animationConfig.animation : '',
    className,
  );

  if (lines > 1) {
    const lineClasses = [];
    for (let i = 0; i < lines; i++) {
      const lineWidth = i === lines - 1 ? 'w-3/4' : 'w-full';
      lineClasses.push(
        mergeClasses(
          baseClasses,
          lineWidth,
          i < lines - 1 && 'mb-2',
        ),
      );
    }
    return lineClasses.join(' ');
  }

  return baseClasses;
}

/**
 * Gets avatar skeleton classes.
 *
 * @param {Object} options - Avatar options.
 * @param {string} [options.size] - Skeleton size.
 * @param {string} [options.variant] - Skeleton variant.
 * @param {string} [options.radius] - Border radius.
 * @param {string} [options.animation] - Animation type.
 * @param {string} [options.className] - Additional classes.
 * @param {boolean} [options.disabled] - Disabled state.
 * @param {boolean} [options.loading] - Loading state.
 * @param {string} [options.dimension] - Custom dimension.
 * @returns {string} Merged avatar skeleton classes.
 */
export function getSkeletonAvatarClasses({
  size = SKELETON_DEFAULTS.size,
  variant = SKELETON_DEFAULTS.variant,
  radius = SKELETON_DEFAULTS.radius,
  animation = SKELETON_DEFAULTS.animation,
  className = '',
  disabled = false,
  loading = true,
  dimension = '',
}) {
  const sizeConfig = getSkeletonSize(size);
  const variantConfig = getSkeletonVariant(variant);
  const animationConfig = getSkeletonAnimation(animation);

  return mergeClasses(
    'relative overflow-hidden shrink-0',
    variantConfig.background,
    dimension || sizeConfig.width,
    dimension || sizeConfig.height,
    getSkeletonRadius('full'),
    animationConfig.transition,
    disabled && 'opacity-50 cursor-not-allowed',
    loading ? animationConfig.animation : '',
    'aspect-square',
    className,
  );
}

/**
 * Gets card skeleton classes.
 *
 * @param {Object} options - Card options.
 * @param {string} [options.size] - Skeleton size.
 * @param {string} [options.variant] - Skeleton variant.
 * @param {string} [options.radius] - Border radius.
 * @param {string} [options.animation] - Animation type.
 * @param {string} [options.className] - Additional classes.
 * @param {boolean} [options.disabled] - Disabled state.
 * @param {boolean} [options.loading] - Loading state.
 * @param {number} [options.lines] - Number of text lines.
 * @param {boolean} [options.showImage] - Show image placeholder.
 * @param {boolean} [options.showAvatar] - Show avatar placeholder.
 * @returns {string} Merged card skeleton classes.
 */
export function getSkeletonCardClasses({
  size = SKELETON_DEFAULTS.size,
  variant = SKELETON_DEFAULTS.variant,
  radius = SKELETON_DEFAULTS.radius,
  animation = SKELETON_DEFAULTS.animation,
  className = '',
  disabled = false,
  loading = true,
  lines = 3,
  showImage = true,
  showAvatar = false,
}) {
  const sizeConfig = getSkeletonSize(size);
  const variantConfig = getSkeletonVariant(variant);
  const animationConfig = getSkeletonAnimation(animation);

  const cardClasses = mergeClasses(
    'relative overflow-hidden flex flex-col',
    variantConfig.background,
    getSkeletonRadius(radius),
    'p-4',
    sizeConfig.gap,
    animationConfig.transition,
    disabled && 'opacity-50 cursor-not-allowed',
    loading ? animationConfig.animation : '',
    className,
  );

  const imageHeight = showImage ? 'h-32 w-full' : '';
  const avatarClasses = showAvatar ? 'h-10 w-10 rounded-full' : '';

  const contentLines = [];
  for (let i = 0; i < lines; i++) {
    const lineWidth = i === lines - 1 ? 'w-3/4' : 'w-full';
    contentLines.push(
      mergeClasses(
        'h-3 bg-gray-200 dark:bg-gray-700 rounded',
        lineWidth,
        i < lines - 1 && 'mb-2',
      ),
    );
  }

  return {
    container: cardClasses,
    image: imageHeight,
    avatar: avatarClasses,
    content: contentLines.join(' '),
  };
}

/* ---------------------------------- */
/* Validation Utilities               */
/* ---------------------------------- */

/**
 * Validates if a variant is valid.
 *
 * @param {string} variant - The variant to check.
 * @returns {boolean} True if valid.
 */
export function isValidVariant(variant) {
  return variant ? Object.keys(SKELETON_VARIANTS).includes(variant) : false;
}

/**
 * Validates if a size is valid.
 *
 * @param {string} size - The size to check.
 * @returns {boolean} True if valid.
 */
export function isValidSize(size) {
  return size ? Object.keys(SKELETON_SIZES).includes(size) : false;
}

/**
 * Validates if a radius is valid.
 *
 * @param {string} radius - The radius to check.
 * @returns {boolean} True if valid.
 */
export function isValidRadius(radius) {
  return radius ? Object.keys(SKELETON_RADIUS).includes(radius) : false;
}

/* ---------------------------------- */
/* Accessibility Helpers              */
/* ---------------------------------- */

/**
 * Generates accessibility helpers for skeleton components.
 *
 * @param {Object} state - Component state.
 * @param {string} [state.label] - Skeleton label.
 * @param {boolean} [state.disabled] - Disabled state.
 * @param {boolean} [state.loading] - Loading state.
 * @returns {Object} Accessibility helper functions.
 */
export function getAccessibilityHelpers({
  label = '',
  disabled = false,
  loading = true,
}) {
  return {
    getRole: () => 'progressbar',
    getAriaLabel: () => label || 'Loading',
    getAriaDisabled: () => disabled || undefined,
    getAriaBusy: () => loading || undefined,
    getAriaValuenow: () => undefined,
    getAriaValuemin: () => 0,
    getAriaValuemax: () => 100,
    getTabIndex: () => (disabled ? -1 : 0),
  };
}

