      <motion.div
        ref={ref}
        className={mergeClasses(
          finalClasses,
          pulseSize,
          'relative inline-flex items-center justify-center',
        )}
        {...motionProps}
        {...ariaProps}
        {...rest}
      >
        {/* Main pulse */}
        <motion.span
          className={mergeClasses(
            'absolute inset-0 rounded-full',
