          closeTooltip();
          isPressed.current = false;
        }
      },
      [disabled, interactive, triggers.click, openTooltip, closeTooltip],
    );

    // Handle click.
    const handleClick = useCallback(() => {
      if (disabled || !interactive || !triggers.click) return;
      if (isPressed.current) {
        closeTooltip();
        isPressed.current = false;
      } else {
        openTooltip();
        isPressed.current = true;
      }
    }, [disabled, interactive, triggers.click, openTooltip, closeTooltip]);

    // Cleanup timers on unmount.
    useEffect(() => {
      return () => {
        clearTimers();
      };
    }, [clearTimers]);

    // Merge refs.
    const mergedRef = useCallback(
      (node) => {
        triggerRef.current = node;
        if (typeof ref === 'function') ref(node);
        else if (ref) ref.current = node;
      },
      [ref],
    );

    // Determine trigger classes.
    const triggerClasses = useMemo(() => {
      const base = mergeClasses(
        'inline-flex',
        disabled && 'opacity-50 cursor-not-allowed pointer-events-none',
        className,
      );
      return responsive ? mergeClasses(base, resolveResponsiveClasses(responsive)) : base;
    }, [disabled, className, responsive]);

    // Motion props - respect reduced motion.
    const motionProps = useMemo(() => {
      if (prefersReducedMotion) {
        return {
          whileHover: undefined,
          whileTap: undefined,
          transition: undefined,
        };
      }
      return {
        whileHover: { scale: TRIGGER_MOTION.hover.scale },
        whileTap: { scale: TRIGGER_MOTION.tap.scale },
        transition: TRIGGER_MOTION.transition,
      };
    }, [prefersReducedMotion]);

    // Accessibility attributes.
    const ariaProps = useMemo(
      () => ({
        role,
        'aria-label': ariaLabel,
        'aria-disabled': disabled || undefined,
        tabIndex: disabled ? -1 : 0,
      }),
      [role, ariaLabel, disabled],
    );

    // Clone child with trigger props.
    const child = children;
    const childProps = {
      ref: mergedRef,
      className: mergeClasses(child.props?.className || '', triggerClasses),
      onMouseEnter: (e) => {
  child.props?.onMouseEnter?.(e);
  handleMouseEnter(e);
},

onMouseLeave: (e) => {
  child.props?.onMouseLeave?.(e);
  handleMouseLeave(e);
},

onFocus: (e) => {
  child.props?.onFocus?.(e);
  handleFocus(e);
},

onBlur: (e) => {
  child.props?.onBlur?.(e);
  handleBlur(e);
},

onKeyDown: (e) => {
  child.props?.onKeyDown?.(e);
  handleKeyDown(e);
},

onClick: (e) => {
  child.props?.onClick?.(e);
  handleClick(e);
},
      ...ariaProps,
      ...motionProps,
      ...rest,
    };

    // If child is a React element, clone it with the props.
    if (React.isValidElement(child)) {
      return cloneElement(child, childProps);
    }

    // Otherwise, wrap the child in a motion.div.
    return (
      <motion.div
        ref={mergedRef}
        className={triggerClasses}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onFocus={handleFocus}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        onClick={handleClick}
        {...ariaProps}
        {...motionProps}
        {...rest}
      >
        {child}
      </motion.div>
    );
  }),
);

TooltipTrigger.displayName = 'TooltipTrigger';

TooltipTrigger.propTypes = {
  /** The trigger element (button, icon, text, etc.). */
  children: PropTypes.node.isRequired,
  /** Called when tooltip open state changes. */
  onOpenChange: PropTypes.func,
  /** Called when tooltip opens. */
  onOpen: PropTypes.func,
  /** Called when tooltip closes. */
  onClose: PropTypes.func,
  /** Interaction trigger type(s). */
  trigger: PropTypes.oneOfType([
    PropTypes.oneOf(['hover', 'focus', 'click']),
    PropTypes.arrayOf(PropTypes.oneOf(['hover', 'focus', 'click'])),
  ]),
  /** Delay before opening (ms). */
  delay: PropTypes.number,
  /** Delay before closing (ms). */
  closeDelay: PropTypes.number,
  /** Disables the trigger. */
  disabled: PropTypes.bool,
  /** Whether trigger is interactive. */
  interactive: PropTypes.bool,
  /** Responsive overrides. */
  responsive: PropTypes.shape({
    xs: PropTypes.string,
    sm: PropTypes.string,
    md: PropTypes.string,
    lg: PropTypes.string,
    xl: PropTypes.string,
  }),
  /** Additional CSS classes. */
  className: PropTypes.string,
  /** ARIA role. */
  role: PropTypes.string,
  /** Accessible label. */
  'aria-label': PropTypes.string,
};

export default TooltipTrigger;

/**
 * KisanO Design System — Tooltip Package
 * TooltipPortal
 *
 * A portal component that renders tooltip content outside the DOM hierarchy
 * of the trigger element. Handles mounting, unmounting, and portal cleanup.
 *
 * Single Responsibility: Render tooltip content via React Portal.
 * Does not handle positioning, triggers, or tooltip state.
 *
 * @module components/ui/Tooltip/TooltipPortal
 */

import { forwardRef, memo, useMemo, useEffect, useState, useRef } from 'react';
import { createPortal } from 'react-dom';
import PropTypes from 'prop-types';
import { motion, AnimatePresence, useReducedMotion } from 'framer-motion';


import {
  mergeClasses,
  resolveResponsiveClasses,
} from './tooltipUtils';

/* ---------------------------------- */
/* Component-specific tokens          */
/* ---------------------------------- */

/** Motion variants for portal entrance/exit. */
const PORTAL_MOTION = {
  initial: { opacity: 0, scale: 0.95 },
  animate: { opacity: 1, scale: 1 },
  exit: { opacity: 0, scale: 0.95 },
  transition: { duration: 0.15, ease: [0.4, 0, 0.2, 1] },
};

/** Default portal container ID. */
const DEFAULT_PORTAL_ID = 'tooltip-portal';

/* ---------------------------------- */
/* Component                          */
/* ---------------------------------- */

/**
 * TooltipPortal – a portal for tooltip content.
 *
 * @component
 * @example
 * <TooltipPortal open={isOpen} containerId="custom-portal">
 *   <div>Tooltip content</div>
 * </TooltipPortal>
 */
const TooltipPortal = memo(
  forwardRef(function TooltipPortal(
    {
      children,
      open = false,
      containerId = DEFAULT_PORTAL_ID,
      container,
      disabled = false,
      animated = true,
      responsive,
      className = '',
      role = 'tooltip',
      'aria-label': ariaLabel,
      ...rest
    },
    ref,
  ) {
    const prefersReducedMotion = useReducedMotion();
    const [portalContainer, setPortalContainer] = useState(null);
  

    // Determine if animation should be applied.
    const shouldAnimate = animated && !prefersReducedMotion && !disabled;

    // Motion props.
    const motionProps = useMemo(() => {
      if (!shouldAnimate) {
        return { initial: false, animate: true, exit: false };
      }
      return PORTAL_MOTION;
    }, [shouldAnimate]);

    // Create or get portal container.
    useEffect(() => {
      if (container) {
        setPortalContainer(container);
        return;
      }

      // Get or create portal container in DOM.
      let portalElement = document.getElementById(containerId);
      if (!portalElement) {
        portalElement = document.createElement('div');
        portalElement.id = containerId;
        portalElement.setAttribute('aria-hidden', 'true');
        document.body.appendChild(portalElement);
      }
      setPortalContainer(portalElement);

      // Cleanup on unmount.
      return () => {
        // Only remove if we created it and it's empty.
        if (portalElement && portalElement.childNodes.length === 0 && !container) {
          document.body.removeChild(portalElement);
        }
      };
    }, [container, containerId]);

    // Portal content classes.
    const portalClasses = useMemo(() => {
      const base = mergeClasses(
        'fixed z-50 pointer-events-none',
        disabled && 'opacity-50 cursor-not-allowed',
        className,
      );
      return responsive ? mergeClasses(base, resolveResponsiveClasses(responsive)) : base;
    }, [disabled, className, responsive]);

    // Accessibility attributes.
    const ariaProps = useMemo(
      () => ({
        role,
        'aria-label': ariaLabel || 'Tooltip portal',
        'aria-hidden': !open || undefined,
        'aria-disabled': disabled || undefined,
      }),
      [role, ariaLabel, open, disabled],
    );

    // If disabled or no portal container, return null.
    if (disabled || !portalContainer) {
      return null;
    }

    // Render portal content.
    return createPortal(
      <AnimatePresence initial={false}>
        {open && (
          <motion.div
            ref={(node) => {
  if (typeof ref === 'function') {
    ref(node);
  } else if (ref) {
    ref.current = node;
  }
}}
            className={portalClasses}
            {...motionProps}
            {...ariaProps}
            {...rest}
          >
            {children}
          </motion.div>
        )}
      </AnimatePresence>,
      portalContainer,
    );
  }),
);

TooltipPortal.displayName = 'TooltipPortal';

TooltipPortal.propTypes = {
  /** Tooltip content to render in portal. */
  children: PropTypes.node,
  /** Whether the portal is open. */
  open: PropTypes.bool,
  /** ID of the portal container element. */
  containerId: PropTypes.string,
  /** Custom container element (overrides containerId). */
  container: PropTypes.instanceOf(HTMLElement),
  /** Disables the portal. */
  disabled: PropTypes.bool,
  /** Whether animation is enabled. */
  animated: PropTypes.bool,
  /** Responsive overrides. */
  responsive: PropTypes.shape({
    xs: PropTypes.string,
    sm: PropTypes.string,
    md: PropTypes.string,
    lg: PropTypes.string,
    xl: PropTypes.string,
  }),
  /** Additional CSS classes. */
  className: PropTypes.string,
  /** ARIA role. */
  role: PropTypes.string,
  /** Accessible label. */
  'aria-label': PropTypes.string,
};

export default TooltipPortal;

