const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

// Generate dummy calendar days
const generateDays = () => {
  const days = [];
  for (let i = 1; i <= 30; i++) {
    days.push({
      date: i,
      jobs: i === 12 || i === 15 ? 2 : i === 18 ? 1 : 0,
      isBlocked: i === 22 || i === 23,
      isCompleted: i < 12 && i % 2 !== 0
    });
  }
  return days;
};

