      try {
        const response = await api.get('/equipment');
        if (response.data?.success) {
          const myFleet = response.data.data.filter(eq => eq.ownerId === user?.id);
          setEquipment(myFleet);
        }
      } catch (error) {
        console.error("Error fetching fleet", error);
      } finally {
        setLoading(false);
      }
